// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/ITEEVerifier.sol";

/// @title MockTEEVerifier - demo verifier that accepts any quote with the right structure.
///         In production, this would be Phala's on-chain SGX verifier or Automata.
contract MockTEEVerifier is ITEEVerifier {
    mapping(bytes32 => bool) public revokedMrEnclaves;
    address public owner;

    event MrEnclaveRevoked(bytes32 mrEnclave);
    event MrEnclaveApproved(bytes32 mrEnclave);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function revokeMrEnclave(bytes32 mr) external onlyOwner {
        revokedMrEnclaves[mr] = true;
        emit MrEnclaveRevoked(mr);
    }

    function approveMrEnclave(bytes32 mr) external onlyOwner {
        revokedMrEnclaves[mr] = false;
        emit MrEnclaveApproved(mr);
    }

    /// @notice Quote layout: [mr_enclave: 32][mr_signer: 32][issuedAt: 32] (total 96 bytes).
    ///         Each field is ABI-encoded (32-byte aligned).
    function verifyQuote(
        bytes calldata quote,
        bytes32 expectedMrEnclave,
        bytes32 expectedMrSigner,
        uint64 minIssuedAt
    ) external view override returns (bool valid) {
        if (quote.length != 96) return false;
        if (revokedMrEnclaves[expectedMrEnclave]) return false;

        bytes32 actualMr = abi.decode(quote[:32], (bytes32));
        bytes32 actualSigner = abi.decode(quote[32:64], (bytes32));
        uint256 tsFull = abi.decode(quote[64:], (uint256));
        uint64 issuedAt = uint64(tsFull);

        if (issuedAt < minIssuedAt) return false;
        if (actualMr != expectedMrEnclave) return false;
        if (actualSigner != expectedMrSigner) return false;
        return true;
    }
}

src/MockZkMLVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/ITEEVerifier.sol";

/// @title MockZkMLVerifier - demo verifier for zkML proofs.
///         In production, this would verify an EZKL halo2/PLONK proof.
contract MockZkMLVerifier is IZkMLVerifier {
    address public owner;
    mapping(bytes32 => bool) public revokedCircuits;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function revokeCircuit(bytes32 circuitHash) external onlyOwner {
        revokedCircuits[circuitHash] = true;
    }

    function approveCircuit(bytes32 circuitHash) external onlyOwner {
        revokedCircuits[circuitHash] = false;
    }

    /// @notice Proof layout: [random: 32][commitment: 32] (total 64 bytes)
    ///         commitment = keccak256(publicInputsHash || circuitHash)
    function verifyProof(
        bytes32 circuitHash,
        bytes32 publicInputsHash,
        bytes calldata proof
    ) external view override returns (bool valid) {
        if (revokedCircuits[circuitHash]) return false;
        if (proof.length < 64) return false;
        bytes32 expected = keccak256(abi.encodePacked(publicInputsHash, circuitHash));
        // Read the last 32 bytes via calldata slicing + abi.decode
        bytes32 actual = abi.decode(proof[proof.length - 32:], (bytes32));
        return actual == expected;
    }
}

src/ProofLatticeRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "./interfaces/IERC8004.sol";
import "./interfaces/ITEEVerifier.sol";

interface IERC721Like {
    function ownerOf(uint256 tokenId) external view returns (address);
}

/// @title ProofLatticeRegistry
/// @notice On-chain reputation + TEE-attested + zkML-bound registry for AI agents on Mantle.
///         Wraps ERC-8004 Identity Registry and adds TEE measurement + zkML circuit binding,
///         proof history, and oracle-updatable trust score.
contract ProofLatticeRegistry is Ownable, ReentrancyGuard {
    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    struct AgentMetadata {
        bytes32 teeMrEnclave;        // TEE measurement of agent runtime
        bytes32 teeMrSigner;         // TEE signer measurement
        bytes32 zkmlCircuitHash;     // Hash of zkML circuit (0 if not used)
        address teeVerifier;         // TEE attestation verifier contract
        address zkmlVerifier;        // zkML verifier contract (0 if not used)
        uint64  firstSeen;           // Block timestamp at registration
        uint64  lastAttested;        // Last block timestamp the agent re-attested
        uint16  trustScore;          // 0-1000, oracle-updated
        uint16  attestationCount;    // How many times the agent re-attested
        bool    bgaCertified;        // BGA-certified social-good flag
        bool    active;              // Active agent
    }

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------

    IERC8004Identity public immutable identityRegistry;
    address public trustOracle;          // Off-chain trust engine signer
    address public bountyBoard;          // Bounty board that can slash
    address public arena;                // Demosthenes arena that can award

    mapping(uint256 => AgentMetadata) public agentMeta;   // agentId => metadata
    mapping(uint256 => bytes32[]) public proofHistory;    // agentId => ring of proof hashes
    mapping(uint256 => bytes32[]) public teeHistory;      // agentId => ring of TEE quotes
    mapping(address => uint256) public agentIdByOperator; // operator => agentId
    mapping(bytes32 => bool)    public seenProofs;        // proof hash => already seen
    mapping(bytes32 => bool)    public seenTeeQuotes;     // mr enclave + nonce => seen

    // Track # of agents and total proofs
    uint256 public totalAgents;
    uint256 public totalProofs;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    event AgentRegistered(
        uint256 indexed agentId,
        address indexed operator,
        bytes32 teeMrEnclave,
        bytes32 zkmlCircuitHash,
        address teeVerifier
    );

    event AgentReattested(
        uint256 indexed agentId,
        bytes32 indexed newMrEnclave,
        uint16 attestationCount
    );

    event ProofSubmitted(
        uint256 indexed agentId,
        bytes32 indexed proofHash,
        uint256 blockNumber
    );

    event TrustScoreUpdated(
        uint256 indexed agentId,
        uint16 oldScore,
        uint16 newScore,
        uint256 blockNumber
    );

    event BgaCertified(uint256 indexed agentId, bool certified);
    event AgentSlashed(uint256 indexed agentId, uint16 oldScore, uint16 newScore, string reason);

    // ------------------------------------------------------------------
    // Modifiers
    // ------------------------------------------------------------------

    modifier onlyOperator(uint256 agentId) {
        require(IERC721Like(address(identityRegistry)).ownerOf(agentId) == msg.sender, "Not operator");
        _;
    }

    modifier onlyOracle() {
        require(msg.sender == trustOracle, "Not oracle");
        _;
    }

    modifier onlyBountyBoard() {
        require(msg.sender == bountyBoard, "Not bounty board");
        _;
    }

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    constructor(
        address _identityRegistry,
        address _trustOracle,
        address _teeVerifier
    ) Ownable(msg.sender) {
        require(_identityRegistry != address(0), "Zero identity registry");
        identityRegistry = IERC8004Identity(_identityRegistry);
        trustOracle = _trustOracle;
        // teeVerifier at the registry level is just a default suggestion;
        // per-agent verifier is set at registration.
    }

    // ------------------------------------------------------------------
    // Admin
    // ------------------------------------------------------------------

    function setTrustOracle(address newOracle) external onlyOwner {
        trustOracle = newOracle;
    }

    function setBountyBoard(address newBountyBoard) external onlyOwner {
        bountyBoard = newBountyBoard;
    }

    function setArena(address newArena) external onlyOwner {
        arena = newArena;
    }

    function setBgaCertified(uint256 agentId, bool certified) external onlyOwner {
        agentMeta[agentId].bgaCertified = certified;
        emit BgaCertified(agentId, certified);
    }

    // ------------------------------------------------------------------
    // Registration
    // ------------------------------------------------------------------

    /// @notice Register a new agent with TEE attestation (and optional zkML circuit).
    /// @param agentURI The ERC-8004 registration file URI (IPFS, HTTPS, etc.)
    /// @param teeMrEnclave The expected TEE measurement register
    /// @param teeMrSigner The expected TEE signer measurement
    /// @param teeVerifier The TEE verifier contract for this agent
    /// @param teeQuote The TEE quote bytes
    /// @param zkmlCircuitHash The hash of the zkML circuit (or 0 if unused)
    /// @param zkmlVerifier The zkML verifier address (or 0 if unused)
    /// @return agentId The newly registered agent ID
    function registerWithAttestation(
        string calldata agentURI,
        bytes32 teeMrEnclave,
        bytes32 teeMrSigner,
        address teeVerifier,
        bytes calldata teeQuote,
        bytes32 zkmlCircuitHash,
        address zkmlVerifier
    ) external nonReentrant returns (uint256) {
        require(teeVerifier != address(0), "Zero TEE verifier");
        require(teeMrEnclave != bytes32(0), "Zero mr_enclave");

        // 0. Operator must not already be registered
        require(agentIdByOperator[msg.sender] == 0, "Operator already registered");

        // 1. Verify TEE quote
        require(
            ITEEVerifier(teeVerifier).verifyQuote(
                teeQuote, teeMrEnclave, teeMrSigner, uint64(block.timestamp - 1 days)
            ),
            "Invalid TEE quote"
        );

        // 2. Check TEE quote hasn't been used (globally)
        bytes32 quoteKey = keccak256(teeQuote);
        require(!seenTeeQuotes[quoteKey], "TEE quote replay");
        seenTeeQuotes[quoteKey] = true;

        // 3. Mint ERC-8004 identity
        bytes32[] memory attestations = new bytes32[](2);
        attestations[0] = teeMrEnclave;
        attestations[1] = zkmlCircuitHash;
        uint256 agentId = identityRegistry.register(msg.sender, agentURI, attestations);

        // 4. Store metadata
        agentMeta[agentId] = AgentMetadata({
            teeMrEnclave:    teeMrEnclave,
            teeMrSigner:     teeMrSigner,
            zkmlCircuitHash: zkmlCircuitHash,
            teeVerifier:     teeVerifier,
            zkmlVerifier:    zkmlVerifier,
            firstSeen:       uint64(block.timestamp),
            lastAttested:    uint64(block.timestamp),
            trustScore:      500,            // baseline
            attestationCount: 1,
            bgaCertified:    false,
            active:          true
        });

        teeHistory[agentId].push(keccak256(teeQuote));

        // 5. Index by operator
        agentIdByOperator[msg.sender] = agentId;

        totalAgents++;

        emit AgentRegistered(agentId, msg.sender, teeMrEnclave, zkmlCircuitHash, teeVerifier);
        emit AgentReattested(agentId, teeMrEnclave, 1);
        return agentId;
    }

    /// @notice Re-attest TEE measurement (e.g., after runtime upgrade)
    function reattest(
        uint256 agentId,
        bytes32 newMrEnclave,
        bytes32 newMrSigner,
        bytes calldata teeQuote
    ) external onlyOperator(agentId) nonReentrant {
        AgentMetadata storage m = agentMeta[agentId];
        require(m.active, "Not active");
        require(
            ITEEVerifier(m.teeVerifier).verifyQuote(
                teeQuote, newMrEnclave, newMrSigner, uint64(block.timestamp - 1 days)
            ),
            "Invalid TEE quote"
        );

        bytes32 quoteKey = keccak256(teeQuote);
        require(!seenTeeQuotes[quoteKey], "TEE quote replay");
        seenTeeQuotes[quoteKey] = true;

        m.teeMrEnclave = newMrEnclave;
        m.teeMrSigner = newMrSigner;
        m.lastAttested = uint64(block.timestamp);
        m.attestationCount += 1;

        teeHistory[agentId].push(keccak256(teeQuote));

        emit AgentReattested(agentId, newMrEnclave, m.attestationCount);
    }

    // ------------------------------------------------------------------
    // Proofs
    // ------------------------------------------------------------------

    /// @notice Submit a zkML proof hash for a decision the agent made.
    /// @param agentId The agent ID
    /// @param proofHash The hash of the zkML proof (off-chain prover posts this)
    /// @param publicInputsHash The hash of the public inputs (decision context)
    /// @param proof Optional: the proof bytes (for verifier-integrated mode)
    function submitProof(
        uint256 agentId,
        bytes32 proofHash,
        bytes32 publicInputsHash,
        bytes calldata proof
    ) external onlyOperator(agentId) {
        require(agentMeta[agentId].active, "Not active");
        require(!seenProofs[proofHash], "Proof already seen");
        seenProofs[proofHash] = true;

        // If zkML verifier is configured, verify the proof on-chain
        if (agentMeta[agentId].zkmlVerifier != address(0) && proof.length > 0) {
            require(
                IZkMLVerifier(agentMeta[agentId].zkmlVerifier).verifyProof(
                    agentMeta[agentId].zkmlCircuitHash, publicInputsHash, proof
                ),
                "Invalid zkML proof"
            );
        }

        proofHistory[agentId].push(proofHash);
        totalProofs++;

        emit ProofSubmitted(agentId, proofHash, block.number);
    }

    // ------------------------------------------------------------------
    // Trust Score Updates
    // ------------------------------------------------------------------

    /// @notice Update the trust score (called by the trust oracle / engine)
    function updateTrustScore(uint256 agentId, uint16 newScore) external onlyOracle {
        require(newScore <= 1000, "Score > 1000");
        uint16 old = agentMeta[agentId].trustScore;
        agentMeta[agentId].trustScore = newScore;
        emit TrustScoreUpdated(agentId, old, newScore, block.number);
    }

    /// @notice Bounty board slashes an agent (called only by the bounty board)
    function slash(uint256 agentId, uint16 newScore, string calldata reason) external onlyBountyBoard {
        require(newScore < agentMeta[agentId].trustScore, "Score not lower");
        uint16 old = agentMeta[agentId].trustScore;
        agentMeta[agentId].trustScore = newScore;
        emit AgentSlashed(agentId, old, newScore, reason);
        emit TrustScoreUpdated(agentId, old, newScore, block.number);
    }

    /// @notice Arena awards an agent (called only by the arena contract)
    function award(uint256 agentId, uint16 newScore) external {
        require(msg.sender == arena, "Not arena");
        require(newScore > agentMeta[agentId].trustScore, "Score not higher");
        uint16 old = agentMeta[agentId].trustScore;
        agentMeta[agentId].trustScore = newScore;
        emit TrustScoreUpdated(agentId, old, newScore, block.number);
    }

    /// @notice Deactivate an agent (operator resignation)
    function deactivate(uint256 agentId) external onlyOperator(agentId) {
        agentMeta[agentId].active = false;
    }

    // ------------------------------------------------------------------
    // View helpers
    // ------------------------------------------------------------------

    function getAgent(uint256 agentId) external view returns (AgentMetadata memory) {
        return agentMeta[agentId];
    }

    function getProofHistoryLength(uint256 agentId) external view returns (uint256) {
        return proofHistory[agentId].length;
    }

    function getTeeHistoryLength(uint256 agentId) external view returns (uint256) {
        return teeHistory[agentId].length;
    }
}

src/XBountyBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ProofLatticeRegistry.sol";

/// @title XBountyBoard
/// @notice Permissionless bounty board: anyone can stake MNT to challenge an
///         agent's reputation claim. If a Demosthenes round invalidates the
///         agent's proofs, the accuser wins (most of) the slashed stake.
contract XBountyBoard is Ownable, ReentrancyGuard {
    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    enum BountyState { OPEN, CHALLENGED, RESOLVED_GUILTY, RESOLVED_INNOCENT, EXPIRED }

    struct Bounty {
        uint256 bountyId;
        uint256 accusedAgentId;
        address accuser;
        string  claimURI;             // IPFS hash with evidence
        bytes32 claimHash;            // Hash of the claim
        uint256 stake;                // MNT staked by accuser
        uint256 challengedRoundId;    // Demosthenes round that resolves it
        BountyState state;
        uint64  createdAt;
        uint64  resolvedAt;
    }

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------

    ProofLatticeRegistry public registry;
    address public arena;                 // DemosthenesArena
    address public feeRecipient;
    uint256 public bountyCount;
    uint256 public constant ACCUSER_REWARD_BPS = 7000;   // 70% to accuser on guilty
    uint256 public constant AGENT_REWARD_BPS   = 2000;   // 20% back to agent
    uint256 public constant FEE_BPS            = 1000;   // 10% to fee recipient

    mapping(uint256 => Bounty) public bounties;
    mapping(uint256 => uint256[]) public agentBounties;   // agentId => bountyIds[]

    uint256 public totalStake;
    uint256 public totalSlashed;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    event BountyFiled(
        uint256 indexed bountyId,
        uint256 indexed accusedAgentId,
        address indexed accuser,
        uint256 stake,
        string claimURI
    );

    event BountyChallenged(uint256 indexed bountyId, uint256 indexed roundId);
    event BountyResolvedGuilty(uint256 indexed bountyId, uint256 payout);
    event BountyResolvedInnocent(uint256 indexed bountyId, uint256 refund);
    event BountyExpired(uint256 indexed bountyId);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    constructor(address _registry, address _arena, address _feeRecipient) Ownable(msg.sender) {
        registry = ProofLatticeRegistry(_registry);
        arena = _arena;
        feeRecipient = _feeRecipient;
    }

    // ------------------------------------------------------------------
    // File a bounty
    // ------------------------------------------------------------------

    /// @notice File a bounty accusing an agent of faking reputation.
    ///         The accuser must stake MNT; if guilty, 70% is paid back as reward.
    function fileBounty(
        uint256 accusedAgentId,
        string calldata claimURI,
        bytes32 claimHash
    ) external payable nonReentrant returns (uint256 bountyId) {
        require(msg.value > 0, "Zero stake");
        (, , , , , , , , , , bool active) = registry.agentMeta(accusedAgentId);
        require(active, "Agent not active");

        bountyId = ++bountyCount;
        bounties[bountyId] = Bounty({
            bountyId: bountyId,
            accusedAgentId: accusedAgentId,
            accuser: msg.sender,
            claimURI: claimURI,
            claimHash: claimHash,
            stake: msg.value,
            challengedRoundId: 0,
            state: BountyState.OPEN,
            createdAt: uint64(block.timestamp),
            resolvedAt: 0
        });

        agentBounties[accusedAgentId].push(bountyId);
        totalStake += msg.value;

        emit BountyFiled(bountyId, accusedAgentId, msg.sender, msg.value, claimURI);
    }

    // ------------------------------------------------------------------
    // Trigger a Demosthenes round to resolve the bounty
    // ------------------------------------------------------------------

    /// @notice Link this bounty to a Demosthenes round; the round's verdict resolves it.
    function linkToRound(uint256 bountyId, uint256 roundId) external {
        require(msg.sender == arena, "Not arena");
        Bounty storage b = bounties[bountyId];
        require(b.state == BountyState.OPEN, "Not open");
        b.challengedRoundId = roundId;
        b.state = BountyState.CHALLENGED;
        emit BountyChallenged(bountyId, roundId);
    }

    // ------------------------------------------------------------------
    // Resolve
    // ------------------------------------------------------------------

    function resolveGuilty(uint256 bountyId, uint16 newAgentScore) external {
        require(msg.sender == arena, "Not arena");
        Bounty storage b = bounties[bountyId];
        require(b.state == BountyState.CHALLENGED, "Not challenged");

        b.state = BountyState.RESOLVED_GUILTY;
        b.resolvedAt = uint64(block.timestamp);

        // Slash the agent
        (, , , , , , , uint16 currentScore, , , ) = registry.agentMeta(b.accusedAgentId);
        if (newAgentScore < currentScore) {
            registry.slash(b.accusedAgentId, newAgentScore, "Bounty resolved guilty");
        }

        // Distribute stake
        uint256 accuserPayout = (b.stake * ACCUSER_REWARD_BPS) / 10000;
        uint256 feePayout     = (b.stake * FEE_BPS) / 10000;
        uint256 totalPayout   = accuserPayout + feePayout;
        totalSlashed += b.stake;

        (bool ok1, ) = b.accuser.call{value: accuserPayout}("");
        require(ok1, "Accuser payout failed");
        if (feePayout > 0 && feeRecipient != address(0)) {
            (bool ok2, ) = feeRecipient.call{value: feePayout}("");
            require(ok2, "Fee payout failed");
        }

        emit BountyResolvedGuilty(bountyId, totalPayout);
    }

    function resolveInnocent(uint256 bountyId) external {
        require(msg.sender == arena, "Not arena");
        Bounty storage b = bounties[bountyId];
        require(b.state == BountyState.CHALLENGED, "Not challenged");

        b.state = BountyState.RESOLVED_INNOCENT;
        b.resolvedAt = uint64(block.timestamp);

        // Refund accuser (with small slash to deter spam)
        uint256 refund = (b.stake * 80) / 100;  // 80% refund
        uint256 fee    = b.stake - refund;
        totalSlashed += fee;

        (bool ok1, ) = b.accuser.call{value: refund}("");
        require(ok1, "Refund failed");
        if (fee > 0 && feeRecipient != address(0)) {
            (bool ok2, ) = feeRecipient.call{value: fee}("");
            require(ok2, "Fee payout failed");
        }

        emit BountyResolvedInnocent(bountyId, refund);
    }

    // ------------------------------------------------------------------
    // Expiry
    // ------------------------------------------------------------------

    function expireBounty(uint256 bountyId) external {
        Bounty storage b = bounties[bountyId];
        require(b.state == BountyState.OPEN, "Not open");
        require(block.timestamp > b.createdAt + 30 days, "Too early");

        b.state = BountyState.EXPIRED;
        b.resolvedAt = uint64(block.timestamp);

        (bool ok, ) = b.accuser.call{value: b.stake}("");
        require(ok, "Refund failed");

        emit BountyExpired(bountyId);
    }

    // ------------------------------------------------------------------
    // View helpers
    // ------------------------------------------------------------------

    function getBounty(uint256 bountyId) external view returns (Bounty memory) {
        return bounties[bountyId];
    }

    function getBountiesForAgent(uint256 agentId) external view returns (uint256[] memory) {
        return agentBounties[agentId];
    }
}

